	localparam JRG_OFFSET_END_BIT = 5;
	localparam JMP_OFFSET_WIDTH = 8;
	localparam JOF_OFFSET_WIDTH = 6;
	localparam JOC_OFFSET_WIDTH = 6;
	localparam JRG_OFFSET_WIDTH = 5;
