	reg [15:0] cond_mask;
	reg cond_all;
	reg cond_inv;
	wire hit;
	localparam [2:0] mda_pkg_BR_JRG = 3'd2;
	assign is_jrg = br_type == mda_pkg_BR_JRG;
	localparam [2:0] mda_pkg_BR_JOC = 3'd5;
	localparam [2:0] mda_pkg_BR_JOF = 3'd4;
