			mda_pkg_BR_JOF: pc_offset = {{4 {instr[JOF_OFFSET_START_BIT]}}, instr[JOF_OFFSET_START_BIT:JOF_OFFSET_END_BIT]};
			mda_pkg_BR_JOC: pc_offset = {{4 {instr[JOC_OFFSET_HI_START_BIT]}}, instr[JOC_OFFSET_HI_START_BIT:JOC_OFFSET_HI_END_BIT], instr[JOC_OFFSET_LO_START_BIT:JOC_OFFSET_LO_END_BIT]};
			mda_pkg_BR_JRG: pc_offset = {{5 {instr[JRG_OFFSET_START_BIT]}}, instr[JRG_OFFSET_START_BIT:JRG_OFFSET_END_BIT]};
