					suffix_pend = suffix_pend | (id_t[t] & pend[t]);
					suffix_rd = suffix_rd | ({mda_pkg_REG_ADDR_WIDTH {id_t[t]}} & rd_q[t]);
					suffix_imm8 = suffix_imm8 | ({8 {id_t[t]}} & imm8_q[t]);
