	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			pend <= 1'sb0;
		else begin : sv2v_autoblock_2
			reg signed [31:0] t;
			for (t = 0; t < mda_pkg_NUM_THREADS; t = t + 1)
