	localparam signed [31:0] mda_isa_pkg_RD_LO = 13;
	always @(posedge clk) begin : sv2v_autoblock_3
		reg signed [31:0] t;
		for (t = 0; t < mda_pkg_NUM_THREADS; t = t + 1)
			if (((id_t[t] && id_v) && !pend[t]) && lli_first) begin
				rd_q[t] <= instr[mda_isa_pkg_RD_HI:mda_isa_pkg_RD_LO];
				imm8_q[t] <= instr[12:5];
