	assign tr_rd_we = w_ex_we;
	assign tr_rd = w_ex_addr;
	assign tr_wdata = w_ex_data;
	assign tr_ld_valid = w_ld_we;
	assign tr_ld_thread = w_ld_thread;
	assign tr_ld_rd = w_ld_addr;
	assign tr_ld_data = w_ld_data;
