module tt_um_mda (
	ui_in,
	uo_out,
	uio_in,
	uio_out,
	uio_oe,
	ena,
	clk,
	rst_n
);
	input wire [7:0] ui_in;
	output wire [7:0] uo_out;
	input wire [7:0] uio_in;
	output wire [7:0] uio_out;
	output wire [7:0] uio_oe;
	input wire ena;
	input wire clk;
	input wire rst_n;
	wire rst_n_sync;
	mda_sync #(.WIDTH(1)) u_rst_sync(
		.clk(clk),
		.d(rst_n),
		.q(rst_n_sync)
	);
	reg rst_q;
	wire go;
	always @(posedge clk or negedge rst_n_sync)
		if (!rst_n_sync)
			rst_q <= 1'b0;
		else
			rst_q <= 1'b1;
	assign go = rst_n_sync & ~rst_q;
	wire tr_valid;
	wire tr_rd_we;
	wire tr_zn_we;
	wire tr_z;
	wire tr_n;
	wire tr_c_we;
	wire tr_c;
	wire tr_taken;
	wire tr_fault;
	wire tr_ld_valid;
	wire [1:0] tr_thread;
	wire [1:0] tr_ld_thread;
	localparam signed [31:0] mda_pkg_IMEM_ADDR_WIDTH = 10;
	wire [9:0] tr_pc;
	localparam signed [31:0] mda_pkg_INSTR_WIDTH = 16;
	wire [15:0] tr_instr;
	localparam signed [31:0] mda_pkg_REG_ADDR_WIDTH = 3;
	wire [2:0] tr_rd;
	wire [2:0] tr_ld_rd;
	localparam signed [31:0] mda_pkg_DATA_WIDTH = 32;
	wire [31:0] tr_wdata;
	wire [31:0] tr_mem_addr;
	wire [31:0] tr_ld_data;
	localparam signed [31:0] mda_pkg_FLAGS_WIDTH = 16;
	wire [15:0] tr_flags;
	wire [2:0] tr_fault_cause;
	localparam signed [31:0] mda_pkg_DMEM_ADDR_WIDTH = 8;
	mda_top u_top(
		.clk(clk),
		.rst_n(rst_n_sync),
		.go(go),
		.entry_pc0({mda_pkg_IMEM_ADDR_WIDTH {1'b0}}),
		.entry_pc1({mda_pkg_IMEM_ADDR_WIDTH {1'b0}}),
		.entry_pc2({mda_pkg_IMEM_ADDR_WIDTH {1'b0}}),
		.imem_ld_we(1'b0),
		.imem_ld_addr({mda_pkg_IMEM_ADDR_WIDTH {1'b0}}),
		.imem_ld_data({mda_pkg_INSTR_WIDTH {1'b0}}),
		.dmem_ld_we(1'b0),
		.dmem_ld_addr({mda_pkg_DMEM_ADDR_WIDTH {1'b0}}),
		.dmem_ld_data({mda_pkg_DATA_WIDTH {1'b0}}),
		.tr_valid(tr_valid),
		.tr_thread(tr_thread),
		.tr_pc(tr_pc),
		.tr_instr(tr_instr),
		.tr_rd_we(tr_rd_we),
		.tr_rd(tr_rd),
		.tr_wdata(tr_wdata),
		.tr_flags(tr_flags),
		.tr_zn_we(tr_zn_we),
		.tr_z(tr_z),
		.tr_n(tr_n),
		.tr_c_we(tr_c_we),
		.tr_c(tr_c),
		.tr_taken(tr_taken),
		.tr_fault(tr_fault),
		.tr_fault_cause(tr_fault_cause),
		.tr_mem_addr(tr_mem_addr),
		.tr_ld_valid(tr_ld_valid),
		.tr_ld_thread(tr_ld_thread),
		.tr_ld_rd(tr_ld_rd),
		.tr_ld_data(tr_ld_data)
	);
	reg [7:0] hash;
	wire [7:0] fold_ex;
	wire [7:0] fold_ld;
	assign fold_ex = ((tr_wdata[7:0] ^ tr_wdata[15:8]) ^ tr_wdata[23:16]) ^ tr_wdata[31:24];
	assign fold_ld = ((tr_ld_data[7:0] ^ tr_ld_data[15:8]) ^ tr_ld_data[23:16]) ^ tr_ld_data[31:24];
	always @(posedge clk or negedge rst_n_sync)
		if (!rst_n_sync)
			hash <= 8'd0;
		else
			hash <= ((({hash[6:0], hash[7]} ^ (tr_valid & tr_rd_we ? fold_ex : 8'd0)) ^ (tr_ld_valid ? fold_ld : 8'd0)) ^ {6'd0, tr_taken, tr_fault}) ^ (tr_valid ? tr_pc[7:0] : 8'd0);
	assign uo_out = hash;
	assign uio_out = 8'd0;
	assign uio_oe = 8'd0;
	wire _unused = &{ena, ui_in, uio_in, 1'b0};
endmodule
